export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const v = u - g * t;
  const y = u * t - g * t * t / 2;
  const apexH = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 40, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 300, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const py = 380 - y / 2.2 * 300;
  const bx = 170;
  o.push(sdk.circle('ball.toss', bx, py, 26));
  o.push(...sdk.vector('vec.v', { x: bx, y: py }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: bx + 40, y: py }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
  o.push(sdk.callout(215, 100, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = [];
  const n = 20;
  for (let i = 0; i <= n; i++) { const tt = Math.min(t, T) * i / n; pts.push({ x: tt, y: u - g * tt }); }
  const full = [];
  for (let i = 0; i <= n; i++) { const tt = 1.8 * i / n; const vv = u - g * tt; if (vv >= -5.5) full.push({ x: tt, y: vv }); }
  const series = [{ label: 'v = u - g t', kind: 'line', points: full }];
  if (t > 0) series.push({ label: 'so far', kind: 'line', points: pts });
  o.push(sdk.plot('plot.vt', { x: 340, y: 40, w: 290, h: 340, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series }));
  o.push(sdk.text('plot.vt.note', 480, 405, 'slope a = -g = ' + sdk.format(-g, 1), { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: apexH, height: y, velocity: v, acceleration: -g, force: F } };
}
